WITH unpacked AS (SELECT id, plan, effective_from, currency, tier_limits, ARRAY_MIN(tier_prices) AS lowest_price, SLICE(tier_limits, 1, 2) AS first_two_limits, AGGREGATE(tier_prices, 0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price FROM price_tiers) SELECT CASE WHEN lowest_price >= 34 THEN 'LARGE' ELSE 'SMALL' END AS lowest_price_tier, CASE WHEN avg_tier_price >= 31 THEN 'HIGH' ELSE 'LOW' END AS avg_tier_price_tier, ROUND(SUM(lowest_price) / NULLIF(COUNT(CASE WHEN currency = 'EUR' THEN 1 END), 0), 2) AS lowest_price_per_eur, MIN(lowest_price) AS min_lowest_price, APPROX_PERCENTILE(avg_tier_price, 0.95) AS avg_tier_price_p95 FROM unpacked GROUP BY CASE WHEN lowest_price >= 34 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN avg_tier_price >= 31 THEN 'HIGH' ELSE 'LOW' END
